// Each facade's agent skill as a file to download: the SKILL.md its package ships, generated by the engine.
import type { APIRoute, GetStaticPaths } from "astro";
import { getCollection } from "astro:content";

export const getStaticPaths = (async () => {
	const facades = await getCollection("facades");
	return facades.map((entry) => ({ params: { slug: entry.id }, props: { skill: entry.data.skill } }));
}) satisfies GetStaticPaths;

export const GET: APIRoute = ({ props }) =>
	new Response(String(props["skill"]), { headers: { "content-type": "text/markdown; charset=utf-8" } });
